constexpr bool nationalSpecies(std::uint16_t s) noexcept{return s>=1 && s<=493;}
constexpr std::uint16_t offerCount(std::uint16_t s) noexcept{return nationalSpecies(s)?kDiamondPearlRanges[s].count:0;}
constexpr std::uint16_t offerPacked(std::uint16_t s,std::uint16_t i) noexcept{
    return nationalSpecies(s)&&i<offerCount(s)?kDiamondPearlOffers[kDiamondPearlRanges[s].offset+i]:0;
}
constexpr bool completeOrderedOffers(std::uint16_t s) noexcept {
    return nationalSpecies(s)&&kDiamondPearlLevelChronologyMonotone[s]&&offerCount(s)>0;
}
constexpr bool machineCompatible(std::uint16_t species,bool hgss,bool hidden,std::uint8_t number) noexcept{
    if(!nationalSpecies(species)||!number||number>(hidden?8:92))return false;
    const std::uint8_t bit=hidden?static_cast<std::uint8_t>(91+number):static_cast<std::uint8_t>(number-1);
    const auto lo=hgss?kHeartGoldSoulSilverMachineLow[species]:kDiamondPearlMachineLow[species];
    const auto hi=hgss?kHeartGoldSoulSilverMachineHigh[species]:kDiamondPearlMachineHigh[species];
    return bit<64?((lo>>bit)&1ULL)!=0:((hi>>(bit-64))&1ULL)!=0;
}
constexpr bool tutorCompatible(std::uint16_t species,std::uint16_t move) noexcept{
    if(!nationalSpecies(species)||!move)return false;
    for(std::uint8_t i=0;i<kHeartGoldSoulSilverTutorMoves.size();++i)
        if(kHeartGoldSoulSilverTutorMoves[i]==move &&
           ((kHeartGoldSoulSilverTutorMask[species]>>i)&1ULL))return true;
    return false;
}
